"""Ticket ids are generated by code in a fixed format, never by the model."""

import re

from app.tickets.repository import TicketRepository, new_ticket_id


def test_ticket_id_format() -> None:
    assert re.fullmatch(r"GN-[0-9A-F]{8}", new_ticket_id())


def test_create_and_get() -> None:
    tickets = TicketRepository()

    ticket = tickets.create(
        user_id="cliente1988",
        category="fraud_or_security",
        priority="urgent",
        origin="router",
        operator_summary="Lojista suspeita de clonagem de cartão.",
        customer_message="Vamos encaminhar seu caso.",
        language="pt",
    )

    assert tickets.get(ticket.id) == ticket
    assert tickets.get("GN-00000000") is None
    assert tickets.count() == 1


def test_ids_are_unique() -> None:
    tickets = TicketRepository()
    ids = {
        tickets.create(
            user_id="u",
            category="other",
            priority="low",
            origin="support",
            operator_summary="s",
            customer_message="m",
            language="en",
        ).id
        for _ in range(50)
    }
    assert len(ids) == 50
